// dzrp::translateCondition: DeZog breakpoint conditions (JavaScript after DeZog replaced the registers and numbers)
// in the core condition language. The expected truths are JavaScript's: by hand below, and generated by DeZog's own
// token replacement and eval in node (testdata/debugger/conditions/dezog-cases.tsv,
// tools/verification/dezog/gen_condition_cases.mjs). The core program must give them, and refuse what it would
// answer differently.

#include <gtest/gtest.h>

#include <cstring>
#include <fstream>
#include <sstream>
#include <string>

#include "_helpers/testpathhelper.h"
#include "dezogcondition.h"
#include "debugger/breakpoints/breakpointcondition.h"
#include "emulator/cpu/z80.h"

namespace
{
class DezogCondition_test : public ::testing::Test
{
protected:
    Z80Registers _cpu{};

    void SetUp() override
    {
        std::memset(&_cpu, 0, sizeof(_cpu));
        _cpu.pc = 0x8000;
        _cpu.sp = 0xFF00;
        _cpu.af = 0x1234;  // A #12, F #34
        _cpu.bc = 0x00FF;
        _cpu.de = 0xCAFE;
        _cpu.hl = 0xDEAD;
        _cpu.ix = 0x1111;
        _cpu.iy = 0x2222;
        _cpu.alt.af = 0x3344;
        _cpu.alt.bc = 0x4455;
        _cpu.i = 0x3F;
        _cpu.r_low = 0x21;
        _cpu.r_hi = 0x80;  // R #A1
        _cpu.im = 1;
    }

    // The truth of the translated condition on _cpu
    bool Holds(const std::string& condition)
    {
        std::string core;
        std::string reason;
        EXPECT_TRUE(dzrp::translateCondition(condition, core, reason)) << condition << ": " << reason;
        std::string error;
        BreakpointConditionPtr program = BreakpointConditionProgram::Compile(core, BRK_COND_EXEC, nullptr, error);
        EXPECT_TRUE(program) << condition << " -> " << core << ": " << error;
        if (!program)
            return false;
        BreakpointConditionContext x;
        x.cpu = &_cpu;
        const BreakpointConditionResult result = program->Evaluate(x);
        EXPECT_NE(result, BreakpointConditionResult::Error) << condition << " -> " << core;
        return result == BreakpointConditionResult::True;
    }

    std::string Refused(const std::string& condition)
    {
        std::string core;
        std::string reason;
        EXPECT_FALSE(dzrp::translateCondition(condition, core, reason)) << condition << " -> " << core;
        return reason;
    }
};
} // namespace

TEST_F(DezogCondition_test, NumbersAsDeZogReadsThem)
{
    EXPECT_TRUE(Holds("A == 18"));
    EXPECT_TRUE(Holds("A == 0x12"));
    EXPECT_TRUE(Holds("A == $12"));
    EXPECT_TRUE(Holds("A == 12h"));
    EXPECT_TRUE(Holds("A == 10010b"));
    EXPECT_TRUE(Holds("HL == 0DEADh"));
    EXPECT_TRUE(Holds("A == 018")) << "decimal, not octal: DeZog parses the token";
    EXPECT_TRUE(Holds("PC == 0x18000")) << "DeZog masks every number to 16 bits";
    EXPECT_TRUE(Holds("PC == 98304"));
}

TEST_F(DezogCondition_test, RegistersInAnyCase)
{
    EXPECT_TRUE(Holds("pc == 0x8000 && sp == 0xFF00"));
    EXPECT_TRUE(Holds("a == 0x12 && F == 0x34 && b == 0 && c == 255"));
    EXPECT_TRUE(Holds("IXH == 0x11 && iyl == 0x22"));
    EXPECT_TRUE(Holds("AF' == 0x3344 && a' == 0x33 && F' == 0x44 && BC' == 0x4455 && c' == 0x55"));
    EXPECT_TRUE(Holds("I == 0x3F && R == 0xA1 && IR == 0x3FA1 && IM == 1"));
}

TEST_F(DezogCondition_test, JavaScriptPrecedenceAndValues)
{
    // Comparisons bind tighter than & (JavaScript, C): (A & 0x10) == 0x10 needs the brackets, without them it is
    // A & (0x10 == 0x10) = A & 1 = 0
    EXPECT_TRUE(Holds("(A & 0x10) == 0x10"));
    EXPECT_FALSE(Holds("A & 0x10 == 0x10"));
    EXPECT_TRUE(Holds("A + 1 * 2 == 20"));
    EXPECT_TRUE(Holds("HL % 0x100 == 0xAD"));
    EXPECT_TRUE(Holds("-A + 18 == 0"));
    EXPECT_TRUE(Holds("~A == -19"));
    EXPECT_TRUE(Holds("(HL >> 8) == 0xDE && (A << 4) == 0x120 && (HL >>> 12) == 13"));
    EXPECT_TRUE(Holds("(A == 0x12) + 1 == 2")) << "a truth counts 1";
    EXPECT_TRUE(Holds("(A == 0x12) == 1")) << "loose equality converts the truth";
    EXPECT_TRUE(Holds("(A == 0x12) === (B == 0)"));
    EXPECT_TRUE(Holds("A === 18 && A !== 19"));
    EXPECT_TRUE(Holds("!B && !!A"));
    EXPECT_TRUE(Holds("B || C")) << "&& / || at the top: only the truth counts";
    EXPECT_FALSE(Holds("B && C"));
    EXPECT_TRUE(Holds("1 < A < 3")) << "(1 < A) < 3: true < 3";
    EXPECT_TRUE(Holds("A ^ 0x10 | B")) << "(A ^ 0x10) | B = 2";
    EXPECT_FALSE(Holds("A ^ 0x12 | B"));
}

TEST_F(DezogCondition_test, WhatJavaScriptAnswersDifferentlyIsRefused)
{
    EXPECT_NE(Refused("HL / 2 == 0x6F56").find("fraction"), std::string::npos);
    EXPECT_NE(Refused("LABEL == 1").find("register"), std::string::npos) << "labels are DeZog's";
    EXPECT_NE(Refused("A == FFh").find("register"), std::string::npos) << "letter-led: it could be a label";
    EXPECT_NE(Refused("(B || C) == 1").find("number"), std::string::npos) << "|| gives an operand in JavaScript";
    EXPECT_NE(Refused("(A == 1) === 0").find("strict"), std::string::npos);
    EXPECT_NE(Refused("A % B == 0").find("zero"), std::string::npos) << "NaN when B is 0: true in DeZog";
    EXPECT_NE(Refused("(HL * DE) & 1").find("32 bits"), std::string::npos) << "JavaScript truncates to 32 bits";
    EXPECT_NE(Refused("HL << 20").find("32 bits"), std::string::npos);
    EXPECT_NE(Refused("A << B").find("0..31"), std::string::npos);
    EXPECT_NE(Refused("(A - 20) >> 1").find("negative"), std::string::npos);
    EXPECT_NE(Refused("HL * HL * HL * HL").find("2^53"), std::string::npos);
    EXPECT_FALSE(Refused("A = 1").empty()) << "an assignment";
    EXPECT_FALSE(Refused("A++ == 1").empty());
    EXPECT_FALSE(Refused("A--1").empty()) << "a syntax error in JavaScript";
    EXPECT_FALSE(Refused("A ? 1 : 0").empty());
    EXPECT_FALSE(Refused("A == 'x'").empty());
    EXPECT_FALSE(Refused("A == 0X12").empty()) << "DeZog's tokenizer takes 0x only";
    EXPECT_FALSE(Refused("A == 12H").empty()) << "and h only";
    EXPECT_FALSE(Refused("A == 1F").empty());
    EXPECT_FALSE(Refused("A == 123456789012345678").empty());
    EXPECT_FALSE(Refused("Math.max(A, B)").empty());
    EXPECT_FALSE(Refused("  ").empty());
}

TEST_F(DezogCondition_test, GeneratedCasesAgreeWithJavaScript)
{
    std::ifstream file(TestPathHelper::GetTestDataPath("debugger/conditions/dezog-cases.tsv"));
    ASSERT_TRUE(file.is_open());
    std::string line;
    int cases = 0;
    int translated = 0;
    while (std::getline(file, line))
    {
        if (line.empty() || line[0] == '#')
            continue;
        const size_t tab1 = line.find('\t');
        const size_t tab2 = line.rfind('\t');
        ASSERT_NE(tab1, tab2) << line;
        const std::string condition = line.substr(0, tab1);
        const char truth = line[tab2 + 1];
        std::istringstream values(line.substr(tab1 + 1, tab2 - tab1 - 1));
        unsigned v[15] = {};
        for (unsigned& x : v)
            values >> std::hex >> x;
        _cpu.pc = static_cast<uint16_t>(v[0]);
        _cpu.sp = static_cast<uint16_t>(v[1]);
        _cpu.af = static_cast<uint16_t>(v[2]);
        _cpu.bc = static_cast<uint16_t>(v[3]);
        _cpu.de = static_cast<uint16_t>(v[4]);
        _cpu.hl = static_cast<uint16_t>(v[5]);
        _cpu.ix = static_cast<uint16_t>(v[6]);
        _cpu.iy = static_cast<uint16_t>(v[7]);
        _cpu.alt.af = static_cast<uint16_t>(v[8]);
        _cpu.alt.bc = static_cast<uint16_t>(v[9]);
        _cpu.alt.de = static_cast<uint16_t>(v[10]);
        _cpu.alt.hl = static_cast<uint16_t>(v[11]);
        _cpu.i = static_cast<uint8_t>(v[12]);
        _cpu.r_low = static_cast<uint8_t>(v[13]);
        _cpu.r_hi = static_cast<uint8_t>(v[13] & 0x80);
        _cpu.im = static_cast<uint8_t>(v[14]);
        cases++;

        std::string core;
        std::string reason;
        if (!dzrp::translateCondition(condition, core, reason))
            continue;
        // DeZog throws on this text: the core must not have taken it (it would hide the error behind a false)
        ASSERT_NE(truth, 'E') << condition << " -> " << core;
        std::string error;
        BreakpointConditionPtr program = BreakpointConditionProgram::Compile(core, BRK_COND_EXEC, nullptr, error);
        ASSERT_TRUE(program) << condition << " -> " << core << ": " << error;
        BreakpointConditionContext x;
        x.cpu = &_cpu;
        const BreakpointConditionResult result = program->Evaluate(x);
        ASSERT_NE(result, BreakpointConditionResult::Error) << condition;
        ASSERT_EQ(result == BreakpointConditionResult::True, truth == '1') << condition << " -> " << core;
        translated++;
    }
    EXPECT_GT(cases, 1000);
    // Most random texts contain something refused somewhere; the share taken says the subset is not empty
    EXPECT_GT(translated, cases / 5) << translated << " of " << cases << " translated";
}
